    ["biology-medicine","tsytolohii-histolohii-ta-reproduktyvnoi-medytsyny","Кафедра цитології, гістології та репродуктивної медицини","https://knu.ua/ua/departments/bm/"]
  ]$departments$::jsonb;
begin
  if exists (
    select 1 from jsonb_array_elements(v_rows) department
    where not exists (
      select 1 from public.universities university
      join public.academic_units unit on unit.university_id = university.id
      where university.slug = 'knu' and unit.slug = department->>0
    )
  ) then
    raise exception 'KNU_DEPARTMENT_UNIT_MISSING';
  end if;
  insert into public.academic_departments
    (university_id, academic_unit_id, slug, name, source_url, source_verified_on, is_active)
  select university.id, unit.id, department->>1, department->>2, department->>3, date '2026-10-29', true
  from jsonb_array_elements(v_rows) department
  join public.universities university on university.slug = 'knu'
  join public.academic_units unit on unit.university_id = university.id and unit.slug = department->>0
  on conflict (academic_unit_id, slug) do update set
    name = excluded.name, source_url = excluded.source_url,
    source_verified_on = excluded.source_verified_on, is_active = true;
end
$catalogue$;
commit;
